//! Frozen source-map validation controls for request-local index reuse.
use zil_base::{
    CompileResult, ExpansionRole, FileId, Fingerprint, Limits, ModuleId, NodeId, ResultCategory,
    SourceMap, SourceMapEntry, SourceMapId, SourceTarget, SourceUnit, Span,
};

fn sources(ids: &[u32]) -> Vec<SourceUnit> {
    ids.iter()
        .enumerate()
        .map(|(index, id)| {
            SourceUnit::new(FileId(*id), ModuleId(index as u32 + 20), "source.zil", "éx")
        })
        .collect()
}

fn valid() -> SourceMap {
    SourceMap {
        // This sidecar has never required its module_id to name a source.
        module_id: ModuleId(99),
        entries: vec![
            SourceMapEntry {
                id: SourceMapId(0),
                target: SourceTarget::Node(NodeId(1)),
                origin: Span::new(FileId(7), 0, 2),
                role: ExpansionRole::Source,
                related: Vec::new(),
                parent: None,
            },
            SourceMapEntry {
                id: SourceMapId(1),
                target: SourceTarget::Span(Span::new(FileId(8), 0, 3)),
                origin: Span::new(FileId(7), 2, 3),
                role: ExpansionRole::TemporaryRead,
                related: vec![Span::new(FileId(9), 0, 2)],
                parent: Some(SourceMapId(0)),
            },
            SourceMapEntry {
                id: SourceMapId(2),
                target: SourceTarget::Parameter {
                    function: NodeId(3),
                    index: 0,
                },
                origin: Span::new(FileId(10), 0, 3),
                role: ExpansionRole::ReceiverExplicit,
                related: vec![Span::new(FileId(7), 0, 2)],
                parent: Some(SourceMapId(1)),
            },
        ],
    }
}

fn cases() -> Vec<SourceMap> {
    let mut maps = vec![SourceMap::new(ModuleId(99)), valid()];
    let mut bad = valid();
    bad.entries[0].id = SourceMapId(9);
    maps.push(bad);
    let mut bad = valid();
    bad.entries[0].parent = Some(SourceMapId(1));
    maps.push(bad);
    let mut bad = valid();
    bad.entries[1].target = bad.entries[0].target.clone();
    bad.entries[1].origin.file = FileId(123);
    maps.push(bad);
    let mut bad = valid();
    bad.entries[0].origin = Span::new(FileId(7), 1, 2);
    maps.push(bad);
    let mut bad = valid();
    bad.entries[0].origin.file = FileId(123);
    maps.push(bad);
    let mut bad = valid();
    bad.entries[1].related[0].end = 4;
    maps.push(bad);
    let mut bad = valid();
    bad.entries[1].target = SourceTarget::Span(Span::new(FileId(8), 1, 2));
    maps.push(bad);
    maps
}

fn matrix(mut validate: impl FnMut(&SourceMap, &Limits) -> CompileResult<()>) -> String {
    let maps = cases();
    let mut trace = String::new();
    // A successful source index may precede an entry failure. The following
    // valid map also repeats targets, which must be unique only within a map.
    for index in [2, 1, 1, 0] {
        trace.push_str(&format!(
            "warm:{index}:{:?}\n",
            validate(&maps[index], &Limits::default())
        ));
    }
    for nodes in [0, 1, 2, 3, 4, 5, usize::MAX] {
        for work in 0..=12 {
            let limits = Limits {
                max_nodes: nodes,
                max_analysis_steps: work,
                ..Limits::default()
            };
            for (index, map) in maps.iter().enumerate() {
                trace.push_str(&format!(
                    "{nodes}:{work}:{index}:{:?}\n",
                    validate(map, &limits)
                ));
            }
        }
    }
    Fingerprint::of(trace.as_bytes()).to_hex()
}

#[test]
fn source_identity_errors_are_charged_in_source_order() {
    let empty = SourceMap::new(ModuleId(99));
    for (ids, work, category, message, span) in [
        (
            [7, 7, 8, 9],
            1,
            ResultCategory::ResourceLimit,
            "source-map validation work budget exceeded",
            None,
        ),
        (
            [7, 7, 8, 9],
            2,
            ResultCategory::SafeReject,
            "duplicate source file identity",
            Some(Span::new(FileId(7), 0, 3)),
        ),
        (
            [7, 8, 7, 9],
            2,
            ResultCategory::ResourceLimit,
            "source-map validation work budget exceeded",
            None,
        ),
        (
            [7, 8, 7, 9],
            3,
            ResultCategory::SafeReject,
            "duplicate source file identity",
            Some(Span::new(FileId(7), 0, 3)),
        ),
    ] {
        let errors = empty
            .validate(
                &sources(&ids),
                &Limits {
                    max_analysis_steps: work,
                    ..Limits::default()
                },
            )
            .unwrap_err();
        assert_eq!(errors.len(), 1);
        assert_eq!(errors[0].category, category);
        assert_eq!(errors[0].message, message);
        assert_eq!(errors[0].span, span);
    }
}

#[test]
fn each_map_has_fresh_nodes_targets_and_validation() {
    let sources = sources(&[7, 8, 9, 10]);
    let map = valid();
    let limits = Limits {
        max_nodes: 4,
        max_analysis_steps: 9,
        ..Limits::default()
    };
    map.validate(&sources, &limits).unwrap();
    let error = map
        .validate(
            &sources,
            &Limits {
                max_analysis_steps: 8,
                ..limits.clone()
            },
        )
        .unwrap_err();
    assert_eq!(error[0].category, ResultCategory::ResourceLimit);
    map.validate(&sources, &limits).unwrap();
    let error = map
        .validate(
            &sources,
            &Limits {
                max_nodes: 3,
                ..limits
            },
        )
        .unwrap_err();
    assert_eq!(error[0].message, "source-map node budget exceeded");
    let duplicate = &cases()[4];
    let errors = duplicate
        .validate(&sources, &Limits::default())
        .unwrap_err();
    assert_eq!(
        errors[0].message,
        "source-map target is mapped more than once"
    );
    SourceMap::new(ModuleId(99))
        .validate(
            &[],
            &Limits {
                max_nodes: 0,
                max_analysis_steps: 0,
                ..Limits::default()
            },
        )
        .unwrap();
}

#[test]
fn standalone_validation_matrix_preserves_complete_diagnostics() {
    for ids in [
        &[][..],
        &[7][..],
        &[7, 8, 9, 10][..],
        &[7, 7, 8, 9][..],
        &[7, 8, 7, 9][..],
    ] {
        let sources = sources(ids);
        let digest = matrix(|map, limits| map.validate(&sources, limits));
        println!("CP11_SOURCE_MAP_MATRIX:{ids:?}:{digest}");
    }
}

//! Source-derived integration controls for per-request source-map validation.
use std::collections::BTreeSet;
use zil_base::{FileId, Fingerprint, Limits, ModuleId, ResultCategory, SourceUnit};
use zil_ir::CoreImport;

#[test]
fn project_maps_keep_local_targets_utf8_and_exact_fresh_work() {
    let texts = [
        (
            "main",
            "import model\n// é\nfn main()->i64{let a=model.Cell{};return a.x}",
        ),
        (
            "model",
            "fn seed()->i64=>42\npub struct Cell{pub x:i64=seed()}",
        ),
        ("empty", "// 空模块\n"),
    ];
    let sources = texts
        .iter()
        .enumerate()
        .map(|(i, (name, text))| {
            SourceUnit::new(
                FileId(i as u32),
                ModuleId(i as u32),
                format!("{name}.zil"),
                *text,
            )
        })
        .collect::<Vec<_>>();
    let syntax = sources
        .iter()
        .map(|source| zil_syntax::parse(source).into_result().unwrap())
        .collect::<Vec<_>>();
    let imports = syntax
        .iter()
        .map(|module| {
            module
                .items
                .iter()
                .filter_map(|item| {
                    if let zil_syntax::ast::ItemKind::Import(import) = &item.kind {
                        let position = texts
                            .iter()
                            .position(|(name, _)| import.path == [*name])
                            .unwrap();
                        Some(CoreImport {
                            alias: import.path[0].clone(),
                            module: ModuleId(position as u32),
                            span: item.span,
                        })
                    } else {
                        None
                    }
                })
                .collect::<Vec<_>>()
        })
        .collect::<Vec<_>>();
    let refs = syntax.iter().collect::<Vec<_>>();
    let run =
        |limits: &Limits| zil_expand::expand_program_with_limits(&sources, &refs, &imports, limits);
    let expected = run(&Limits::default()).unwrap();
    for (_, map) in &expected {
        map.validate(&sources, &Limits::default()).unwrap();
    }
    let first = expected[0]
        .1
        .entries
        .iter()
        .map(|entry| &entry.target)
        .collect::<BTreeSet<_>>();
    let second = expected[1]
        .1
        .entries
        .iter()
        .map(|entry| &entry.target)
        .collect::<BTreeSet<_>>();
    assert!(first.intersection(&second).next().is_some());
    assert!(expected[2].1.entries.is_empty());
    let (mut low, mut high) = (0, Limits::default().max_analysis_steps);
    while low + 1 < high {
        let mid = low + (high - low) / 2;
        match run(&Limits {
            max_analysis_steps: mid,
            ..Limits::default()
        }) {
            Ok(value) => {
                assert_eq!(value, expected);
                high = mid;
            }
            Err(errors) => {
                assert!(
                    errors
                        .iter()
                        .all(|error| error.category == ResultCategory::ResourceLimit)
                );
                low = mid;
            }
        }
    }
    let limits = Limits {
        max_analysis_steps: high,
        ..Limits::default()
    };
    assert_eq!(run(&limits).unwrap(), expected);
    let below = run(&Limits {
        max_analysis_steps: high - 1,
        ..limits.clone()
    })
    .unwrap_err();
    assert!(
        below
            .iter()
            .all(|error| error.category == ResultCategory::ResourceLimit)
    );
    assert_eq!(run(&limits).unwrap(), expected);
    println!(
        "CP11_PROJECT_MAP_BOUNDARY:{high}:{}:{below:?}",
        Fingerprint::of(format!("{expected:#?}").as_bytes()).to_hex()
    );
}
